<?php declare(strict_types=1); ?>
<div class="container py-4"><p class="text-primary fw-semibold mb-1">Rol <?= htmlspecialchars($user['role'], ENT_QUOTES, 'UTF-8') ?></p><h1 class="h2">Compras, ventas y pagos</h1><p>Las operaciones confirmadas se muestran con sus detalles históricos.</p>
<section class="bento-card p-4 my-4"><h2 class="h4">Registrar compra pendiente</h2><p class="text-muted">La compra no incrementa existencias hasta que Almacén confirme su recepción.</p><form method="post" action="<?= htmlspecialchars($url->to('/contabilidad/compras'), ENT_QUOTES, 'UTF-8') ?>" class="row g-3"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><div class="col-md-5"><label class="form-label">Proveedor</label><select class="form-select" name="id_proveedor" required><option value="">Selecciona</option><?php foreach ($suppliers as $supplier): ?><option value="<?= (int) $supplier['id_proveedor'] ?>"><?= htmlspecialchars($supplier['nombre'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Fecha</label><input class="form-control" type="date" name="fecha_compra" value="<?= date('Y-m-d') ?>" required></div><div class="col-md-4"><label class="form-label">Observación</label><input class="form-control" name="observacion" maxlength="500"></div>
<?php for ($line = 0; $line < 3; $line++): ?><div class="col-md-6"><label class="form-label">Producto <?= $line + 1 ?></label><select class="form-select" name="id_producto[]"><option value="">Sin línea</option><?php foreach ($products as $product): ?><option value="<?= (int) $product['id_producto'] ?>" data-price="<?= htmlspecialchars($product['precio_compra'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($product['codigo'] . ' · ' . $product['nombre'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-3"><label class="form-label">Cantidad</label><input class="form-control" type="number" min="1" name="cantidad[]"></div><div class="col-6 col-md-3"><label class="form-label">Precio unitario</label><input class="form-control" type="number" min="0" step="0.01" name="precio_unitario[]"></div><?php endfor; ?><div class="col-12"><button class="btn btn-primary">Registrar compra</button></div></form></section>
<section class="bento-card p-4 my-4"><h2 class="h4">Ventas</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido/fecha</th><th>Cliente</th><th>Total</th><th>Estados</th><th>Detalle</th></tr></thead><tbody><?php foreach ($sales as $sale): ?><tr><td><strong><?= htmlspecialchars($sale['codigo_pedido'], ENT_QUOTES, 'UTF-8') ?></strong><br><small><?= htmlspecialchars($sale['fecha_venta'], ENT_QUOTES, 'UTF-8') ?></small></td><td><?= htmlspecialchars($sale['contraparte'], ENT_QUOTES, 'UTF-8') ?></td><td>Bs <?= number_format((float) $sale['total'], 2) ?></td><td><?= htmlspecialchars($sale['estado_pago'] . ' / ' . $sale['estado_logistico'], ENT_QUOTES, 'UTF-8') ?></td><td><details><summary>Ver</summary><ul><?php foreach ($sale['details'] as $detail): ?><li><?= htmlspecialchars($detail['codigo_producto'] . ' · ' . $detail['nombre_producto'], ENT_QUOTES, 'UTF-8') ?>: <?= (int) $detail['cantidad'] ?> × Bs <?= number_format((float) $detail['precio_unitario'], 2) ?> = Bs <?= number_format((float) $detail['subtotal'], 2) ?></li><?php endforeach; ?></ul></details></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="bento-card p-4 my-4"><h2 class="h4">Compras</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Proveedor</th><th>Total</th><th>Estado</th><th>Detalle/acción</th></tr></thead><tbody><?php foreach ($purchases as $purchase): ?><tr><td><?= htmlspecialchars($purchase['fecha_compra'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($purchase['contraparte'], ENT_QUOTES, 'UTF-8') ?></td><td>Bs <?= number_format((float) $purchase['total'], 2) ?></td><td><?= htmlspecialchars($purchase['estado'], ENT_QUOTES, 'UTF-8') ?></td><td><details><summary>Ver detalle</summary><ul><?php foreach ($purchase['details'] as $detail): ?><li><?= htmlspecialchars($detail['codigo_producto'] . ' · ' . $detail['nombre_producto'], ENT_QUOTES, 'UTF-8') ?>: <?= (int) $detail['cantidad'] ?> × Bs <?= number_format((float) $detail['precio_unitario'], 2) ?></li><?php endforeach; ?></ul></details><?php if ($purchase['estado'] === 'pendiente'): ?><form method="post" action="<?= htmlspecialchars($url->to('/contabilidad/compras/' . $purchase['id_compra'] . '/cancelar'), ENT_QUOTES, 'UTF-8') ?>" class="d-flex gap-2 mt-2"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input class="form-control form-control-sm" name="observacion" maxlength="500" placeholder="Motivo"><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="bento-card p-4 my-4"><h2 class="h4">Pagos</h2><?php if ($payments === []): ?><p class="mb-0">No hay pagos registrados.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Pedido</th><th>Método</th><th>Monto</th><th>Estado</th><th>Conciliar</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= htmlspecialchars($payment['codigo_pedido'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($payment['metodo'], ENT_QUOTES, 'UTF-8') ?></td><td>Bs <?= number_format((float) $payment['monto'], 2) ?></td><td><?= htmlspecialchars($payment['estado_conciliacion'], ENT_QUOTES, 'UTF-8') ?></td><td><?php if ($payment['estado_conciliacion'] === 'pendiente'): ?><form method="post" action="<?= htmlspecialchars($url->to('/contabilidad/pagos/' . $payment['id_venta_pago'] . '/conciliar'), ENT_QUOTES, 'UTF-8') ?>" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><select class="form-select form-select-sm" name="estado"><option value="conciliado">Conciliar</option><option value="rechazado">Rechazar</option></select><input class="form-control form-control-sm" name="observacion" maxlength="500" placeholder="Observación"><button class="btn btn-sm btn-primary">Guardar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
